// The generator names a port <dir>_<signal>_<master|slave>; the rules below
// move the block name to the contract port: i_paddr_axi2apb -> i_bus_apb_s_0_paddr,
// o_psel_uart_0 -> o_bus_apb_m_8_psel. First match wins; [] keeps the width.
/* m_qnsc_p_bus AUTO_TEMPLATE(
    .i_clk                               (1'b0),
    .i_rstn                              (1'b1),
    .i_\(protect_en\|slverr_en\)_axi2apb (1'b0),
